-- Appetising customer-facing copy for the 21 seeded Pre Order dishes.
-- Only fills rows the shop has left blank, so staff edits are never overwritten.
UPDATE preorder_items AS p SET description_th = v.description_th, updated_at = now()
FROM (VALUES
('ปูต้ม','ปูสดจากทะเลอ่าวไทย ต้มร้อนด้วยไฟแรงจนเนื้อแน่นหวานฉ่ำ แกะง่าย มันปูสีส้มเข้มข้น จิ้มน้ำจิ้มซีฟู้ดรสจัดแล้วอร่อยจนวางไม่ลง'),
('ไก่แช่เหล้า','ไก่นุ่มหมักในน้ำเหล้าจีนหอมกลมกล่อม แช่เย็นจนเนื้อเด้งฉ่ำ หอมกลิ่นเหล้าอ่อน ๆ ตัดเลี่ยน เสิร์ฟเย็นชื่นใจ เหมาะเป็นจานเปิดโต๊ะ'),
('ซี่โครงหมูอบ','ซี่โครงหมูหมักเครื่องข้ามคืน อบช้าจนเนื้อหลุดล่อนจากกระดูก ผิวนอกเคลือบซอสหวานเค็มเงาวับ กัดคำแรกแล้วหอมกลิ่นเตาอบเต็มปาก'),
('เนื้ออบ','เนื้อชิ้นโตอบจนนุ่มละมุนตัดได้ด้วยส้อม ซอสเข้มข้นซึมถึงใจกลางชิ้น หอมเครื่องเทศอ่อน ๆ เสิร์ฟร้อนพร้อมน้ำซอสราดข้าว'),
('หมูแดง','หมูแดงย่างสูตรต้นตำรับ ผิวนอกเคลือบน้ำหมักสีสวย หวานหอมติดปลายลิ้น เนื้อในนุ่มฉ่ำ หั่นบางพร้อมน้ำราดสูตรร้าน'),
('หมูกรอบ','หมูสามชั้นทอดจนหนังพองกรอบดังกร๊อบ เนื้อในนุ่มชุ่มมัน หั่นเป็นคำพอดี ร้อน ๆ จิ้มแจ่วหรือกินคู่ข้าวสวยก็ฟินไม่แพ้กัน'),
('ขาหมูเยอรมัน','ขาหมูชิ้นใหญ่อบทั้งขา หนังกรอบทั้งแผ่น เนื้อในนุ่มฉ่ำแยกเป็นเส้น เสิร์ฟพร้อมมัสตาร์ดรสจัด จานใหญ่สำหรับแบ่งกันทั้งโต๊ะ'),
('ขนมจีนน้ำยาปู','น้ำยาปูเข้มข้นเคี่ยวจากเนื้อปูก้อนโตกับกะทิสด หอมเครื่องแกงตำเอง ราดบนขนมจีนเส้นนุ่ม เคียงผักสดกรอบ ซดคล่องคอ'),
('แกงหมูลูกเหลียง','แกงพื้นบ้านปักษ์ใต้ หมูนุ่มเคี่ยวกับยอดลูกเหลียงอ่อน น้ำแกงหวานธรรมชาติจากผัก เผ็ดกำลังดี คลุกข้าวสวยร้อน ๆ แล้วหยุดไม่ได้'),
('หมูหวานคั่วน้ำปลา','หมูคั่วน้ำปลาจนเคลือบเงา หวานเค็มหอมไหม้นิด ๆ เคี้ยวเพลินเป็นกับข้าวหรือของว่าง เก็บไว้กินกับข้าวต้มมื้อดึกก็เข้ากัน'),
('ทุเรียน','ทุเรียนคัดพูสวย เนื้อละเอียดหนึบ หวานมันหอมเต็มคำ สุกกำลังดีพร้อมทาน สั่งล่วงหน้าเพื่อให้ทางร้านคัดลูกที่ดีที่สุดไว้ให้'),
('ขนมปังไส้กรอก','ขนมปังนุ่มอบใหม่ห่อไส้กรอกเนื้อแน่น หอมเนยทั้งหลัง กัดแล้วได้ทั้งความนุ่มและความฉ่ำ อุ่นร้อนกินคู่กาแฟยามเช้ากำลังดี'),
('แกงเขียวหวานปลาดุกทะเล','เขียวหวานกะทิสดข้นมัน หอมพริกแกงตำเอง เนื้อปลาดุกทะเลแน่นไม่คาว เผ็ดหอมกำลังดี ราดข้าวสวยหรือกินคู่ขนมจีนก็เข้ากัน'),
('น้ำส้มคั้น','ส้มคั้นสดวันต่อวัน ไม่แต่งกลิ่น ไม่เติมน้ำ เปรี้ยวอมหวานสดชื่น เย็นจับใจ ดื่มคู่มื้ออาหารหรือจิบรับลมทะเลยามบ่าย'),
('พะโล้','พะโล้เคี่ยวไฟอ่อนข้ามชั่วโมง หอมเครื่องพะโล้และอบเชย น้ำซุปสีสวยหวานกลมกล่อม หมูนุ่มไข่ซึมรส ราดข้าวได้ไม่มีเบื่อ'),
('ปูจ๋า','เนื้อปูผสมหมูสับปรุงรสอัดในกระดองแล้วทอดจนหอม นอกกรอบในฉ่ำ จิ้มน้ำจิ้มบ๊วยเปรี้ยวหวานแล้วอร่อยครบรสในคำเดียว'),
('ฮ่อยจ้อ','ไส้ปูและหมูห่อฟองเต้าหู้ นึ่งแล้วทอดจนเหลืองกรอบทั้งชิ้น หั่นเป็นคำหอมกรุ่น จิ้มน้ำจิ้มรสเด็ด ของว่างที่หมดจากโต๊ะเร็วที่สุด'),
('ห่อหมกใบยอ','ห่อหมกเนื้อเนียนนุ่มละมุนลิ้น หอมพริกแกงกับใบยออ่อน ราดหน้าด้วยกะทิสดเยิ้ม ๆ นึ่งร้อนเสิร์ฟในใบตองหอมกรุ่น'),
('ต้มยำพุงปลา','ต้มยำสูตรใต้แท้ รสจัดจ้านกลมกล่อมจากพุงปลาหมักได้ที่ เผ็ดร้อนหอมสมุนไพรสด ซดคำแรกแล้วตื่นทั้งมื้อ'),
('ข้าวขาหมูพะโล้','ขาหมูพะโล้เปื่อยนุ่มจนแตะช้อนก็ขาด ราดบนข้าวสวยร้อน ๆ พร้อมไข่พะโล้และผักกาดดอง ตัดเลี่ยนด้วยน้ำจิ้มกระเทียมพริกสด'),
('แกงกะหรี่ไก่','แกงกะหรี่กะทิหอมเครื่องเทศ ไก่เปื่อยนุ่มกับมันฝรั่งหวานหนึบ ซดคล่องไม่เผ็ดมาก เด็กก็ทานได้ ราดข้าวหรือจิ้มขนมปังก็อร่อย')
) AS v(name_th, description_th)
WHERE p.name_th = v.name_th AND p.description_th = '';
